css:
[data-testid="sidebarColumn"] section:has([aria-label^="Timeline: Trending"]),
[data-testid="sidebarColumn"] aside[aria-label="Who to follow"],
[data-testid="sidebarColumn"] aside[aria-label^="Subscribe to Premium"],
[data-testid="sidebarColumn"] div:has(> aside[aria-label^="Subscribe to Premium"]) {
  display: none !important;
}

js:
// Fallback for when the aria-labels change: hide sidebar blocks by heading.
const hidden = [];
const NOISE = /what.s happening|trends for you|who to follow|subscribe to premium/i;
morse.watch('[data-testid="sidebarColumn"] section, [data-testid="sidebarColumn"] aside', block => {
  const heading = block.querySelector("h2, h1");
  if (heading && NOISE.test(heading.textContent)) {
    block.style.setProperty("display", "none", "important");
    hidden.push(block);
  }
});

return () => hidden.forEach(b => b.style.removeProperty("display"));
